// "Who has access" list in the share dialog. One line per allow entry, sorted.
export function listAccess(node) {
  const seen = new Set();
  const lines = [];
  let current = node;
  let isDirect = true;
  while (current) {
    for (const e of current.acl) {
      if (e.effect !== 'allow') continue;
      const key = `${e.principal}\0${e.role}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (isDirect) {
        lines.push(`${e.principal}: ${e.role}`);
      } else {
        lines.push(`${e.principal}: ${e.role} (inherited from ${current.path()})`);
      }
    }
    if (current.inherit === false) break;
    current = current.parent;
    isDirect = false;
  }
  return lines.sort();
}

