// Collects cleanup callbacks and runs them on close().
export class Scope {
  constructor() {
    this.callbacks = [];
    this.closed = false;
  }

  /** Register a cleanup callback (may be async). */
  defer(cb) {
    if (this.closed) throw new Error('scope already closed');
    this.callbacks.push(cb);
  }

  async close() {
    if (this.closed) return;
    this.closed = true;
    const errors = [];
    for (let i = this.callbacks.length - 1; i >= 0; i--) {
      try {
        await this.callbacks[i]();
      } catch (err) {
        errors.push(err);
      }
    }
    this.callbacks.length = 0;
    if (errors.length === 1) throw errors[0];
    if (errors.length > 1) throw new AggregateError(errors, 'multiple cleanup errors');
  }
}

