// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this._nextSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map(); // seq -> event
    this._bufferedIds = new Set(); // ids currently buffered
    this._appliedIds = new Set(); // ids already applied
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]|Promise<object[]>} events applied as a result of this call, in order.
   * Returns an array for synchronous `apply`; returns a Promise of that array
   * if `apply` returns a thenable; throws synchronously on sync failure and
   * rejects on async failure. State is left consistent in all paths.
   */
  process(event) {
    // Validation failure path (synchronous, no state change):
    // malformed delivery must not corrupt buffer / dedupe sets / seq counters.
    if (!event || typeof event !== 'object') {
      throw new TypeError('event must be an object');
    }
    if (typeof event.id === 'undefined' || event.id === null) {
      throw new TypeError('event.id is required');
    }
    if (typeof event.seq !== 'number' || !Number.isInteger(event.seq)) {
      throw new TypeError('event.seq must be an integer');
    }

    // Idempotency: id already applied or already buffered -> ignore.
    if (this._appliedIds.has(event.id) || this._bufferedIds.has(event.id)) {
      return [];
    }
    // Stale seq: seq already applied (below next expected) -> ignore.
    // Covers seq < startSeq as well since _nextSeq >= startSeq.
    if (event.seq < this._nextSeq) {
      return [];
    }
    // Duplicate seq: a different id already buffered for this seq -> first wins.
    if (this._buffer.has(event.seq)) {
      return [];
    }

    // Buffer early / next event.
    this._buffer.set(event.seq, event);
    this._bufferedIds.add(event.id);

    // Missing seq blocks: if this is not the next expected seq, only buffered.
    // Drain loop below will handle the contiguous case.
    return this._drain([]);
  }

  // Drain contiguous buffered events starting at _nextSeq.
  // Returns array (all-sync success) or Promise<array> (async apply encountered).
  // Throws on sync apply failure; returns rejected promise on async failure.
  // Cleanup on both failure kinds: failed event already removed from buffer
  // + bufferedIds, NOT added to appliedIds, seq NOT advanced, later buffered
  // events stay buffered -> redelivery (same or different id, same seq) can retry.
  _drain(applied) {
    while (this._buffer.has(this._nextSeq)) {
      const ev = this._buffer.get(this._nextSeq);
      // Remove BEFORE apply for reentrancy safety: nested process() calls
      // during apply() must not see / double-apply this event.
      this._buffer.delete(this._nextSeq);
      this._bufferedIds.delete(ev.id);

      let result;
      try {
        result = this.apply(ev);
      } catch (err) {
        // Synchronous failure path: partial progress (earlier `applied` +
        // updated lastSeq/_nextSeq) is preserved; failed seq stays unapplied
        // and unbuffered so a retry is accepted; later seqs stay buffered.
        throw err;
      }

      if (result && typeof result.then === 'function') {
        // Asynchronous apply path: suspend drain until settled.
        return result.then(
          () => {
            // Async success: commit then continue draining (may be sync or async).
            this._appliedIds.add(ev.id);
            this._nextSeq += 1;
            this.lastSeq = ev.seq;
            applied.push(ev);
            return this._drain(applied);
          },
          (err) => {
            // Async rejection path (incl. async-function throw / abort):
            // same cleanup as sync failure, propagate rejection.
            // `applied` successes before this event remain committed.
            throw err;
          }
        );
      }

      // Synchronous success path: commit and continue.
      this._appliedIds.add(ev.id);
      this._nextSeq += 1;
      this.lastSeq = ev.seq;
      applied.push(ev);
    }
    return applied;
  }
}

