// Applies stream events to some state via the `apply` callback.
// Event shape: { id: string, seq: number, type: string, payload?: any }

export class EventProcessor {
  /**
   * @param {(event: object) => void} apply
   * @param {{ startSeq?: number }} [opts]
   */
  constructor(apply, { startSeq = 1 } = {}) {
    this.apply = apply;
    this.startSeq = startSeq;
    this.lastSeq = startSeq - 1;
    this._buffer = new Map();
    this._bufferedIds = new Set();
    this._appliedIds = new Set();
    this._draining = false;
  }

  /** Number of events received but not yet applied. */
  get pendingCount() {
    return this._buffer.size;
  }

  /**
   * Handle one delivered event.
   * @returns {object[]} events applied as a result of this call, in order
   */
  process(event) {
    if (!event || typeof event !== 'object') return [];
    const { id, seq } = event;
    if (id === undefined || id === null) return [];
    if (typeof seq !== 'number' || !Number.isInteger(seq)) return [];
    // Idempotent: already applied or already buffered.
    if (this._appliedIds.has(id)) return [];
    if (this._bufferedIds.has(id)) return [];
    // Stale: seq already applied (includes seq < startSeq since lastSeq = startSeq-1).
    if (seq <= this.lastSeq) return [];
    // Duplicate seq already buffered (first wins).
    if (this._buffer.has(seq)) return [];
    this._buffer.set(seq, event);
    this._bufferedIds.add(id);
    return this._drain();
  }

  _drain() {
    // Re-entrancy guard: if apply() calls process() recursively, just buffer
    // and let the outer drain apply in order to avoid double-apply.
    if (this._draining) return [];
    this._draining = true;
    const applied = [];
    try {
      let next = this.lastSeq + 1;
      while (this._buffer.has(next)) {
        const ev = this._buffer.get(next);
        let result;
        try {
          result = this.apply(ev);
        } catch (err) {
          // Synchronous failure: keep ev buffered (do not delete, do not
          // advance lastSeq, do not mark applied) so a redelivery / later
          // drain can retry; prior successes in this drain are already
          // committed. Propagate to caller; flag cleared in finally.
          throw err;
        }
        // Asynchronous failure (apply returned a thenable that later rejects):
        // process() is synchronous so the event is already considered applied.
        // Attach a catch to avoid unhandled-rejection crashes; unlike sync
        // failures it cannot block ordering because it happens after return.
        if (result && typeof result.then === 'function') {
          Promise.resolve(result).catch(() => {});
        }
        this._buffer.delete(next);
        this._bufferedIds.delete(ev.id);
        this._appliedIds.add(ev.id);
        this.lastSeq = next;
        applied.push(ev);
        next = this.lastSeq + 1;
      }
      return applied;
    } finally {
      this._draining = false;
    }
  }
}
